const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfo(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo((res, err) => {
      if (err) reject(err);
      else resolve(res);
    });
  });
}

async function runAnalysis() {
  try {
    // 1. Geometry (WWF Ecoregions) - find Dry Chaco
    const ecoregions = ee.FeatureCollection('RESOLVE/ECOREGIONS/2017');
    const chacoCand = ecoregions.filter(ee.Filter.stringContains('ECO_NAME', 'Chaco'));
    const dryOnly = chacoCand.filter(ee.Filter.eq('ECO_NAME', 'Dry Chaco'));
    const dryCount = await getInfo(dryOnly.size());
    let regionFC = null;
    let regionName = null;

    if (dryCount > 0) {
      regionFC = dryOnly;
      regionName = 'Dry Chaco';
    } else {
      const chacoCount = await getInfo(chacoCand.size());
      if (chacoCount === 0) {
        console.log('Ecoregion "Chaco" not found.');
        console.log('C1: Empty Collection');
        return;
      }
      const notHumid = chacoCand.filter(ee.Filter.not(ee.Filter.stringContains('ECO_NAME', 'Humid')));
      const nhCount = await getInfo(notHumid.size());
      if (nhCount > 0) {
        regionFC = notHumid;
        regionName = 'Chaco (excluding Humid) [fallback]';
      } else {
        regionFC = chacoCand;
        regionName = 'Chaco (all) [fallback]';
      }
    }
    const regionGeom = regionFC.geometry();
    console.log('Region features: ' + (await getInfo(regionFC.size())) + ' | Using: ' + regionName);

    // 2. Data Acquisition: Hansen Global Forest Change (try versions)
    async function tryGFC(ids) {
      for (let id of ids) {
        try {
          const img = ee.Image(id);
          const bands = await getInfo(img.bandNames());
          if (bands && bands.indexOf('treecover2000') > -1 && bands.indexOf('lossyear') > -1) {
            console.log('GFC dataset: ' + id);
            return img;
          }
        } catch (e) {
          // try next
        }
      }
      return null;
    }
    const gfcIds = [
      'UMD/hansen/global_forest_change_2022_v1_10',
      'UMD/hansen/global_forest_change_2021_v1_9',
      'UMD/hansen/global_forest_change_2020_v1_8'
    ];
    const gfc = await tryGFC(gfcIds);
    if (!gfc) {
      console.log('Failed to load a valid GFC dataset.');
      console.log('D');
      return;
    }

    // 3. Processing: baseline forest (>=30% canopy in 2000) and losses 2001-2019
    const threshold = 30;
    console.log('Baseline canopy threshold: ' + threshold + '%');
    const tree2000 = gfc.select('treecover2000');
    const lossyear = gfc.select('lossyear');
    const baselineMask = tree2000.gte(threshold);
    const lossMask = lossyear.gt(0).and(lossyear.lte(19)); // 2001..2019 inclusive

    const pixelArea = ee.Image.pixelArea();
    const baselineAreaImg = pixelArea.updateMask(baselineMask);
    const lossAreaImg = pixelArea.updateMask(baselineMask).updateMask(lossMask);

    const scale = 1000;
    const maxPixels = 1e12;

    const baseAreaDict = await getInfo(
      baselineAreaImg.reduceRegion({ reducer: ee.Reducer.sum(), geometry: regionGeom, scale: scale, maxPixels: maxPixels })
    );
    const lossAreaDict = await getInfo(
      lossAreaImg.reduceRegion({ reducer: ee.Reducer.sum(), geometry: regionGeom, scale: scale, maxPixels: maxPixels })
    );
    const baseCountDict = await getInfo(
      baselineAreaImg.gt(0).reduceRegion({ reducer: ee.Reducer.count(), geometry: regionGeom, scale: scale, maxPixels: maxPixels })
    );
    const lossCountDict = await getInfo(
      lossAreaImg.gt(0).reduceRegion({ reducer: ee.Reducer.count(), geometry: regionGeom, scale: scale, maxPixels: maxPixels })
    );

    // Extract values
    const baseAreaM2 = baseAreaDict ? baseAreaDict.area : null;
    let lossAreaM2 = lossAreaDict ? lossAreaDict.area : null;
    const basePix = baseCountDict ? baseCountDict.area : 0;
    const lossPix = lossCountDict ? lossCountDict.area : 0;

    if (baseAreaM2 === null) {
      console.log('Baseline area calculation returned null.');
      console.log('C3: Calculation Failure');
      return;
    }
    if (!isFinite(baseAreaM2) || baseAreaM2 <= 0 || basePix === 0) {
      console.log('No valid baseline forest pixels after masking.');
      console.log('C2: No Valid Pixels');
      return;
    }
    if (lossPix === 0) {
      lossAreaM2 = 0; // valid zero loss
    }
    if (lossAreaM2 === null || !isFinite(lossAreaM2) || lossAreaM2 < 0) {
      console.log('Loss area calculation invalid.');
      console.log('C3: Calculation Failure');
      return;
    }

    const baseAreaKm2 = baseAreaM2 / 1e6;
    const lossAreaKm2 = lossAreaM2 / 1e6;
    const remainAreaKm2 = Math.max(0, baseAreaKm2 - lossAreaKm2);
    const percDecrease = (lossAreaM2 / baseAreaM2) * 100;

    // 4. Evidence output (concise)
    console.log('Baseline forest pixels: ' + basePix + ', area: ' + baseAreaKm2.toFixed(1) + ' km²');
    console.log('Loss 2001-2019 pixels: ' + lossPix + ', area: ' + lossAreaKm2.toFixed(1) + ' km²');
    console.log('Decrease 2000->2019: ' + percDecrease.toFixed(2) + '%');
    console.log('Remaining forest 2019: ' + remainAreaKm2.toFixed(1) + ' km²');

    // 5. Final Answer
    if (!isFinite(percDecrease)) {
      console.log('C3: Calculation Failure');
      return;
    }
    if (percDecrease > 10.0) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log('Error: ' + (err && err.message ? err.message : err));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
